const cache = new Map<string, number[][]>();

// Decoded ADM2 boundary rings for one country, or null when the
// dataset has no ADM2 geometry for it.
export function getAdmin2Rings(iso: string): number[][] | null {
  const hit = cache.get(iso);
  if (hit) return hit;
  const packed = PACKED_BY_ISO[iso];
  if (!packed) return null;
  const rings = decodeRings(unpackInts(packed));
  cache.set(iso, rings);
  return rings;
}
